```python
"""Payout executor.

Design
------
State machine: (no row) -> RESERVED -> SENDING -> PAID | FAILED.

* Exactly one invocation can win the compare-and-swap RESERVED -> SENDING. That
  update durably records `last_send_at` *before* the provider is called. Only
  the winner ever calls `provider.send`, and it does so at most once per payout.
  Because send is never repeated, the 24-hour idempotency window cannot expire
  and cause a second transfer. Concurrent or restarted invocations cannot
  duplicate the payout either.
* Any invocation that finds the payout in SENDING never sends. It only calls
  `lookup`:
    - found and accepted  -> PAID
    - found and rejected  -> FAILED
    - None and >= 900s since the recorded send attempt -> FAILED, because no
      transfer can have landed. That time is fixed in the row, so the decision
      cannot race with a newer attempt.
    - None and < 900s, or a timeout -> PENDING, with funds still held.
* A worker killed after the SENDING write but before `send` leaves a row that
  resolves to FAILED after 900s with no money moved. A worker killed after
  `send` leaves a row that `lookup` resolves to PAID or FAILED.
* All finishing writes are compare-and-swap on SENDING. The returned status is
  always re-read from the store, so a concurrent winner is reported accurately.
* Finished payouts return immediately without any provider call.
"""

ProviderTimeout = TimeoutError

_TERMINAL = ("PAID", "FAILED")
_VISIBILITY_WINDOW = 900  # seconds a landed transfer may take to appear in lookup


def _current(store, payout_id):
    """Return the true stored status, mapped to the public result."""
    row = store.get_payout(payout_id)
    if row is None:
        return "PENDING"
    status = row["status"]
    if status in _TERMINAL:
        return status
    return "PENDING"


def _apply_provider_result(store, payout_id, result):
    """Finish the payout based on a provider result dict, if it is conclusive."""
    if not isinstance(result, dict):
        return
    provider_id = result.get("provider_id")
    status = result.get("status")
    if status == "accepted":
        store.finish(payout_id, "SENDING", "PAID", provider_id=provider_id)
    elif status == "rejected":
        store.finish(payout_id, "SENDING", "FAILED",
                     provider_id=provider_id, failure_reason="rejected")
    # Any other value is inconclusive: leave SENDING and report PENDING.


def _send_once(store, provider, payout_id, row):
    """Called only by the invocation that won RESERVED -> SENDING."""
    try:
        result = provider.send(payout_id, row["dest"], row["amount_minor"])
    except ProviderTimeout:
        # Unknown outcome: it may or may not have landed. Never escape.
        return _current(store, payout_id)
    _apply_provider_result(store, payout_id, result)
    return _current(store, payout_id)


def _resolve_sending(store, provider, payout_id, row, now):
    """Resolve a payout in SENDING using only lookup. Never sends."""
    try:
        found = provider.lookup(payout_id)
    except ProviderTimeout:
        return _current(store, payout_id)

    if found is not None:
        _apply_provider_result(store, payout_id, found)
        return _current(store, payout_id)

    # Provider does not know the reference. It is only safe to fail once enough
    # time has passed for any landed transfer to be visible.
    last_send_at = row.get("last_send_at")
    if last_send_at is not None and now - last_send_at >= _VISIBILITY_WINDOW:
        store.finish(payout_id, "SENDING", "FAILED",
                     failure_reason="not_found_after_visibility_window")
    return _current(store, payout_id)


def execute_payout(store, provider, payout_id, account, amount_minor, dest, now) -> str:
    """Returns the payout's current status: "PAID", "FAILED", "PENDING" or "INSUFFICIENT"."""
    row = store.get_payout(payout_id)

    if row is None:
        outcome = store.reserve(payout_id, account, amount_minor, dest)
        if outcome == "INSUFFICIENT":
            return "INSUFFICIENT"
        row = store.get_payout(payout_id)
        if row is None:
            return "PENDING"

    status = row["status"]
    if status in _TERMINAL:
        return status

    if status == "RESERVED":
        # Durably record the attempt time BEFORE calling the provider.
        won = store.update(payout_id, "RESERVED", "SENDING",
                           first_send_at=now, last_send_at=now)
        if won:
            return _send_once(store, provider, payout_id, row)
        # Lost the race: someone else moved it on. Re-read and continue.
        row = store.get_payout(payout_id)
        if row is None:
            return "PENDING"
        status = row["status"]
        if status in _TERMINAL:
            return status

    if status == "SENDING":
        return _resolve_sending(store, provider, payout_id, row, now)

    return _current(store, payout_id)
```
